theorem MIPStarRE.LDT.ExpansionHypercubeGraph.conjTranspose_mul_mul_mono {H K : FiniteHilbertSpace}
    (M : RectangularMatrixOperator H K) {A B : MatrixOperator K} (hAB : A ≤ B) :
    Mᴴ * (A * M) ≤ Mᴴ * (B * M) := by sorry

theorem MIPStarRE.LDT.ExpansionHypercubeGraph.sum_sum_mul_left {α β γ : Type*}
    [Fintype α] [Fintype β] [CommSemiring γ] (c : γ) (f : α → β → γ) :
    ∑ a, ∑ b, c * f a b = c * ∑ a, ∑ b, f a b := by sorry

theorem MIPStarRE.LDT.ExpansionHypercubeGraph.sum_sum_add {α β γ : Type*}
    [Fintype α] [Fintype β] [AddCommMonoid γ] (f g : α → β → γ) :
    ∑ a, ∑ b, (f a b + g a b) = (∑ a, ∑ b, f a b) + ∑ a, ∑ b, g a b := by sorry

theorem MIPStarRE.LDT.ExpansionHypercubeGraph.sum_sum_sub {α β γ : Type*}
    [Fintype α] [Fintype β] [AddCommGroup γ] (f g : α → β → γ) :
    ∑ a, ∑ b, (f a b - g a b) = (∑ a, ∑ b, f a b) - ∑ a, ∑ b, g a b := by sorry
